from typing import Any
from typing import TextIO
from itertools import islice
import csv
import io
import os
REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254
EXCEL_EXTENSIONS = ('.xlsx', '.xlsm')


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def _cell_to_text(value: Any) -> str:
    """Convert an Excel cell value to plain text (single line, no '.0' on whole numbers)."""
    if value is None:
        return ''
    if isinstance(value, float) and value.is_integer():
        value = int(value)
    return str(value).replace('\r', ' ').replace('\n', ' ')


def excel_to_csv_text(path: str, max_rows: int=MAX_ROWS) -> str:
    """Read the first sheet of an .xlsx file and return it as CSV text.

    Each sheet row becomes exactly one CSV line, so line numbers equal Excel row numbers.
    """
    from openpyxl import load_workbook  # imported lazily; only needed for Excel uploads
    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        sheet = workbook.worksheets[0]
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator='\n')
        # header + max_rows data rows + 1 extra so the row cap is still detected
        for sheet_row in islice(sheet.iter_rows(values_only=True), max_rows + 2):
            writer.writerow([_cell_to_text(v) for v in sheet_row])
        return buffer.getvalue()
    finally:
        workbook.close()


def read_upload_as_csv_text(path: str, max_rows: int=MAX_ROWS) -> str:
    """Return CSV text for an uploaded .csv or Excel file."""
    extension = os.path.splitext(path)[1].lower()
    if extension in EXCEL_EXTENSIONS:
        return excel_to_csv_text(path, max_rows)
    if extension in ('.csv', '.txt', ''):
        with open(path, 'r', encoding='utf-8-sig', newline='') as handle:
            return handle.read()
    raise ValueError(f'unsupported file type: {extension or "unknown"} (use .csv or .xlsx)')


def validate_user_upload(path: str, max_rows: int=MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users spreadsheet (CSV or Excel) and report every bad row.

    Validation never stops at the first error. Row numbers are the spreadsheet/file
    row numbers (the header is row 1, so the first data row is row 2).

    Returns:
        {
          "ok": bool,                    # True when there are no invalid rows
          "valid_count": int,
          "invalid_count": int,
          "invalid_rows": [{"row": int, "errors": [str, ...]}, ...],  # sorted by row
          "valid_users": [{"name", "email", "age"}, ...],
        }
    A file-level problem (unreadable file, unsupported type, missing columns) is
    reported as a single entry in invalid_rows (row 1 or row 0) instead of raising.
    """
    try:
        text = read_upload_as_csv_text(path, max_rows)
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        reason = f'could not read file: {exc.__class__.__name__}'
        if isinstance(exc, ValueError) and not isinstance(exc, UnicodeDecodeError):
            reason = str(exc)
        return {'ok': False, 'valid_count': 0, 'invalid_count': 1,
                'invalid_rows': [{'row': 0, 'errors': [reason]}], 'valid_users': []}
    except Exception:
        # Corrupt or unexpected Excel content: report it rather than crash the admin tool.
        return {'ok': False, 'valid_count': 0, 'invalid_count': 1,
                'invalid_rows': [{'row': 0, 'errors': ['file could not be parsed; check that it is a valid spreadsheet']}],
                'valid_users': []}
    valid_users, errors = import_users(text, max_rows)
    errors = sorted(errors, key=lambda e: e['row'])
    return {
        'ok': not errors,
        'valid_count': len(valid_users),
        'invalid_count': len(errors),
        'invalid_rows': errors,
        'valid_users': valid_users,
    }


def format_validation_report(report: dict[str, Any]) -> str:
    """Render the report from validate_user_upload as plain text for staff."""
    lines = [f"{report['valid_count']} valid row(s), {report['invalid_count']} invalid row(s)."]
    for problem in report['invalid_rows']:
        label = f"Row {problem['row']}" if problem['row'] else 'File'
        lines.append(f"{label}: " + '; '.join(problem['errors']))
    return '\n'.join(lines)

